class OrdersController @Inject() (cc: ControllerComponents, orders: OrderService)
    extends AbstractController(cc) {
  def index = Action { implicit request =>
    val page = orders.list(request.session.get("user"))   // domain logic
    Ok(views.html.orders(page))                           // view selection
  }
}
